"""Dataset loading for the proximity-kernel reproduction.

Each loader returns (X, y, meta) where X is a float array with np.nan for
missing values, y are integer class labels and meta holds provenance info.
Raw files are cached under $REPRO_DATA_CACHE/uci (shared across runs).
"""
from __future__ import annotations

import os
import re

import numpy as np

CACHE = os.environ.get(
    "REPRO_DATA_CACHE",
    os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                 ".cache", "datasets", "files"),
)
UCI_DIR = os.path.join(CACHE, "uci")

MISSING = {"?", "", "nan", "NaN", "NA", "N/A", "null", "*"}


def _read_lines(path: str):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return [ln.rstrip("\n") for ln in f]


def _to_float(tok: str) -> float:
    tok = tok.strip().strip("'\"")
    if tok in MISSING:
        return np.nan
    try:
        return float(tok)
    except ValueError:
        return np.nan


def load_hepatitis():
    """UCI Hepatitis: 155 samples, 19 features, 2 classes (Table 2)."""
    path = os.path.join(UCI_DIR, "hepatitis.data")
    rows = [ln for ln in _read_lines(path) if ln.strip()]
    data = [[_to_float(t) for t in ln.split(",")] for ln in rows]
    arr = np.asarray(data, dtype=float)
    y = arr[:, 0].astype(int)
    X = arr[:, 1:]
    meta = {"name": "Hepatitis", "n_samples": int(X.shape[0]),
            "n_features": int(X.shape[1]), "n_classes": int(len(np.unique(y))),
            "source": "https://archive.ics.uci.edu/ml/machine-learning-databases/"
                      "hepatitis/hepatitis.data"}
    return X, _contiguous_codes(y), meta


def load_arff(path: str, label_col_last: bool = True):
    """Minimal ARFF reader (used for the UCI chronic kidney disease file)."""
    lines = _read_lines(path)
    in_data = False
    rows = []
    for ln in lines:
        if ln.strip().lower().startswith("@data"):
            in_data = True
            continue
        if not in_data:
            continue
        s = ln.strip()
        if not s or s.startswith("%"):
            continue
        rows.append([t.strip() for t in s.split(",")])
    out = np.full((len(rows), len(rows[0])), np.nan)
    labels = []
    for r, row in enumerate(rows):
        for c, tok in enumerate(row):
            if label_col_last and c == len(row) - 1:
                labels.append(tok.strip().strip("'\""))
                continue
            out[r, c] = _to_float(tok)
    uniq = sorted(set(labels))
    y = np.array([uniq.index(l) for l in labels], dtype=int)
    return out, y, uniq


def load_kidney():
    """UCI Chronic Kidney Disease: 400 samples, 25 columns (24 features + class)."""
    path = os.path.join(UCI_DIR, "chronic_kidney_disease.arff")
    X, y, classes = load_arff(path)
    meta = {"name": "Kidney", "n_samples": int(X.shape[0]),
            "n_features": int(X.shape[1]), "n_classes": int(len(classes)),
            "source": "https://archive.ics.uci.edu/ml/machine-learning-databases/"
                      "chronic_kidney_disease/chronic_kidney_disease.arff"}
    return X, y, meta


def load_csv_numeric(fname: str, name: str, n_feat=None, label_col=None):
    path = os.path.join(UCI_DIR, fname)
    rows = [ln for ln in _read_lines(path) if ln.strip()]
    data = [[_to_float(t) for t in ln.split(",")] for ln in rows]
    arr = np.asarray(data, dtype=float)
    if label_col is None:
        label_col = arr.shape[1] - 1
    y = arr[:, label_col]
    keep = ~np.isnan(y)
    arr, y = arr[keep], y[keep]
    X = np.delete(arr, label_col, axis=1)
    meta = {"name": name, "n_samples": int(X.shape[0]),
            "n_features": int(X.shape[1]),
            "n_classes": int(len(np.unique(y)))}
    return X, _contiguous_codes(y.astype(int)), meta


def load_categorical(fname: str, name: str, label_col: int = 0,
                     header_cols: int | None = None, weights_col: int | None = None):
    """Dataset whose columns mix categories and numbers -> ordinal codes.

    Categorical tokens are mapped to integer codes (assumption A1); numeric
    tokens keep their value.
    """
    path = os.path.join(UCI_DIR, fname)
    rows = [ln for ln in _read_lines(path) if ln.strip()]
    if header_cols:
        rows = [ln.split(",")[header_cols:] for ln in rows]
        tokens = [r for r in rows]
    else:
        tokens = [ln.split(",") for ln in rows]
    ncol = len(tokens[0])
    cols = list(zip(*tokens))
    out = np.full((len(tokens), ncol - 1), np.nan)
    j_out = 0
    for c in range(ncol):
        if c == label_col:
            continue
        if weights_col is not None and c == weights_col:
            j_out += 1
            continue
        colvals = [t.strip().strip("'\"") for t in cols[c]]
        nums = []
        ok_numeric = True
        for t in colvals:
            if t in MISSING:
                nums.append(np.nan)
                continue
            try:
                nums.append(float(t))
            except ValueError:
                ok_numeric = False
                break
        if ok_numeric:
            out[:, j_out] = np.asarray(nums, dtype=float)
        else:
            cats = sorted({t for t in colvals if t not in MISSING})
            lut = {c_: float(i) for i, c_ in enumerate(cats)}
            out[:, j_out] = [lut.get(t, np.nan) for t in colvals]
        j_out += 1
    labels = [t.strip().strip("'\"") for t in cols[label_col]]
    return out, labels


def _contiguous_codes(y: np.ndarray) -> np.ndarray:
    u = np.unique(y)
    lut = {v: i for i, v in enumerate(u)}
    return np.array([lut[v] for v in y], dtype=int)


def load_dataset(key: str):
    key = key.lower()
    if key == "hepatitis":
        return load_hepatitis()
    if key == "kidney":
        return load_kidney()
    if key == "mammo":
        return load_csv_numeric("mammographic_masses.data", "Mammo", label_col=5)
    if key == "cancer":
        return load_csv_numeric("breast-cancer-wisconsin.data", "Cancer/Wiscom", label_col=10)

